package main

import (
	"bufio"
	"bytes"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevDept string = "   "
var WsRegHours decimal.Decimal = decimal.Zero
var WsOtHours decimal.Decimal = decimal.Zero
var WsGross decimal.Decimal = decimal.Zero
var WsDeptTotal decimal.Decimal = decimal.Zero
var WsDeptCount int64 = 0
var WsGrandTotal decimal.Decimal = decimal.Zero
var WsGrandCount int64 = 0
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var EmpRecData EmpRec
var empLines []string
var empIndex int

func pow10Int(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func parseDisplay(s string, scale int) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.Zero
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return decimal.Zero
	}
	return decimal.New(n, int32(-scale))
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	trunc := v.Truncate(int32(scale))
	total := intDigits + scale
	if total == 0 {
		return decimal.Zero
	}
	scaled := trunc.Shift(int32(scale))
	powTotal := decimal.NewFromInt(pow10Int(total))
	q := scaled.Div(powTotal).Truncate(0)
	lowScaled := scaled.Sub(q.Mul(powTotal))
	return lowScaled.Shift(int32(-scale))
}

func formatEdited(val decimal.Decimal, pic string) string {
	abs := val.Abs()
	dotPos := strings.Index(pic, ".")
	intDigits := 0
	fracDigits := 0
	if dotPos == -1 {
		for _, ch := range pic {
			if ch == 'Z' || ch == '9' {
				intDigits++
			}
		}
	} else {
		for i := 0; i < dotPos; i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				intDigits++
			}
		}
		for i := dotPos + 1; i < len(pic); i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				fracDigits++
			}
		}
	}
	powFracInt := pow10Int(fracDigits)
	powFracDec := decimal.NewFromInt(powFracInt)
	powIntInt := pow10Int(intDigits)
	powIntDec := decimal.NewFromInt(powIntInt)

	scaled := abs.Mul(powFracDec).Truncate(0)
	intPart := scaled.Div(powFracDec).Truncate(0)
	qInt := intPart.Div(powIntDec).Truncate(0)
	intPartMod := intPart.Sub(qInt.Mul(powIntDec))
	fracPart := scaled.Sub(intPart.Mul(powFracDec))

	intStr := fmt.Sprintf("%0*d", intDigits, intPartMod.IntPart())
	fracStr := ""
	if fracDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", fracDigits, fracPart.IntPart())
	}
	firstNonZero := intDigits
	for i := 0; i < intDigits; i++ {
		if intStr[i] != '0' {
			firstNonZero = i
			break
		}
	}
	result := make([]byte, len(pic))
	intIdx := 0
	fracIdx := 0
	for pos := 0; pos < len(pic); pos++ {
		c := pic[pos]
		switch c {
		case '.':
			result[pos] = '.'
		case ',':
			k := intIdx - 1
			if k >= 0 && firstNonZero <= k {
				result[pos] = ','
			} else {
				result[pos] = ' '
			}
		case 'Z', '9':
			isInt := false
			if dotPos == -1 {
				isInt = true
			} else {
				isInt = pos < dotPos
			}
			if isInt {
				digit := intStr[intIdx]
				if intIdx < firstNonZero {
					if c == 'Z' {
						result[pos] = ' '
					} else {
						result[pos] = digit
					}
				} else {
					result[pos] = digit
				}
				intIdx++
			} else {
				digit := fracStr[fracIdx]
				result[pos] = digit
				fracIdx++
			}
		default:
			result[pos] = c
		}
	}
	return string(result)
}

func readEmpFile() []string {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			return []string{}
		}
		fmt.Fprintf(os.Stderr, "Error reading input.dat: %v\n", err)
		os.Exit(1)
	}
	if len(data) == 0 {
		return []string{}
	}
	var lines []string
	reader := bytes.NewReader(data)
	scanner := bufio.NewScanner(reader)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "Error scanning input.dat: %v\n", err)
		os.Exit(1)
	}
	return lines
}

func ReadPara() {
	if empIndex >= len(empLines) {
		WsEofFlag = "Y"
		return
	}
	line := empLines[empIndex]
	empIndex++
	if len(line) < 17 {
		line += strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	EmpRecData.ErId = line[0:5]
	EmpRecData.ErDept = line[5:8]
	EmpRecData.ErHours = parseDisplay(line[8:12], 1)
	EmpRecData.ErRate = parseDisplay(line[12:17], 2)
}

func ProcessPara() {
	if WsFirstFlag == "Y" {
		WsPrevDept = EmpRecData.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecData.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = EmpRecData.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	if EmpRecData.ErHours.GreaterThan(decimal.NewFromInt(40)) {
		WsRegHours = storeDecimal(decimal.NewFromInt(40), 3, 1)
		diff := EmpRecData.ErHours.Sub(decimal.NewFromInt(40))
		WsOtHours = storeDecimal(diff, 3, 1)
	} else {
		WsRegHours = storeDecimal(EmpRecData.ErHours, 3, 1)
		WsOtHours = storeDecimal(decimal.Zero, 3, 1)
	}
	onePointFive := decimal.New(15, -1)
	regPart := WsRegHours.Mul(EmpRecData.ErRate)
	otPart := WsOtHours.Mul(EmpRecData.ErRate).Mul(onePointFive)
	grossExpr := regPart.Add(otPart)
	WsGross = storeDecimal(grossExpr.Round(2), 7, 2)
	WsDeptTotal = storeDecimal(WsDeptTotal.Add(WsGross), 9, 2)
	WsDeptCount = (WsDeptCount + 1) % pow10Int(3)
	WsGrandTotal = storeDecimal(WsGrandTotal.Add(WsGross), 11, 2)
	WsGrandCount = (WsGrandCount + 1) % pow10Int(5)
	WsHoursEd = formatEdited(EmpRecData.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(EmpRecData.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", EmpRecData.ErId, EmpRecData.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	deptCountStr := fmt.Sprintf("%03d", WsDeptCount)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, deptCountStr, WsDeptEd)
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	grandCountStr := fmt.Sprintf("%05d", WsGrandCount)
	fmt.Printf("GRAND TOTAL (%s): %s\n", grandCountStr, WsGrandEd)
}

func MainPara() {
	empLines = readEmpFile()
	empIndex = 0
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	if WsFirstFlag != "Y" {
		DeptBreakPara()
	}
	GrandPara()
}

func main() {
	MainPara()
}
